internal val CURRENCY_NAMES_MY: String =
    "root\u001F4aNAf\u001EAfl\u001EBds\$\u001EB\$\u001Eр.\u001EG\u001EK\u001EB/.\u001E฿\u001ETT\$\u001F4bအာရပ်စော်ဘွားများ ပြည်ထောင်စု ဒါဟမ်း\u001Eအာဖဂန် အာဖဂါနီ\u001Eအယ်ဘေးနီးယား လီခ်\u001Eအာမေးနီးယား ဒရမ်\u001Eနယ်သာလန် အန်တီလန် ဂင်းဒါး\u001Eအန်ဂိုလာ ကွမ်ဇာ\u001Eအာဂျင်တီးနား ပီဆို (၁၉၈၃–၁၉၈၅)\u001Eအာဂျင်တီးနား ပီဆို\u001Eဩစတြေးလျ ဒေါ်လာ\u001Eအရူးဗာ ဖလိုရင်း\u001Eအဇာဘိုင်ဂျန် မာနတ်\u001Eဘော့စနီးယားနှင့် ဟာဇီဂိုဘီးနား ငွေလဲနိုင်သော မတ်က်\u001Eဘာဘေးဒိုးစ် ဒေါ်လာ\u001Eဘင်္ဂလားဒေ့ရှ် တာကာ\u001Eဘယ်လ်ဂျီယမ် ဖရန့်\u001Eဘူလ်ဂေးရီးယား လက်ဖ်\u001Eဘာရိန်း ဒီနား\u001Eဘူရွန်ဒီ ဖရန့်\u001Eဘာမြူဒါ ဒေါ်လာ\u001Eဘရူနိုင်း ဒေါ်လာ\u001Eဘိုလီးဗီးယား ဘိုလီးဗီယားနို\u001Eဘိုလီးဘီးယား ပီဆို\u001Eဘရာဇီး ရီးယဲ\u001Eဘဟားမား ဒေါ်လာ\u001Eဘူတန် အံဂါလ်ထရန်\u001Eဗမာ ကျပ်\u001Eဘော့ဆွာနာ ပုလ\u001Eဘီလာရုစ် ရူဘယ်အသစ် (၁၉၉၄–၁၉၉၉)\u001Eဘီလာရုစ် ရူဘယ်\u001Eဘီလာရုဇ် ရူဘယ် (၂၀၀၀–၂၀၁၆)\u001Eဘလိဇ် ဒေါ်လာ\u001Eကနေဒါ ဒေါ်လာ\u001Eကွန်ဂို ဖရန့်\u001Eဆွစ် ဖရန့်\u001Eချီလီ ပီဆို\u001Eတရုတ် ယွမ်\u001Eကိုလံဘီယာ ပီဆို\u001Eကို့စတာရီကာ ကိုလွန်\u001Eနိုင်ငံခြားငွေလဲလှယ်နိုင်သော ကျူးဘားပီဆို\u001Eကျူးဘား ပီဆို\u001Eကိတ်ပ်ဗာဒီ အက်စ်ခူဒို\u001Eဆိုက်ပရက်စ် ပေါင်\u001Eချက် ခိုရိုနာ\u001Eဂျာမဏီ မတ်\u001Eဂျီဘူတီ ဖရန့်\u001Eဒိန်းမတ် ခရိုဏာ\u001Eဒိုမီနီကန် ပီဆို\u001Eအယ်လ်ဂျီးရီးယား ဒီနာ\u001Eအီဂျစ် ပေါင်\u001Eအီရီထရီးယား နာ့ခ်ဖာ\u001Eစပိန် ပယ်စေးတာ\u001Eအီသီယိုးပီးယား ဘီးယာ\u001Eယူရို\u001Eဖီဂျီ ဒေါ်လာ\u001Eဖော့ကလန်ကျွန်းစု ပေါင်\u001Eပြင်သစ် ဖရန့်\u001Eဗြိတိသျှ ပေါင်\u001Eဂျော်ဂျီယာ လားရီ\u001Eဂါနာ ဆဲဒီ\u001Eဂျီဘရော်လ်တာ ပေါင်\u001Eဂမ်ဘီယာ ဒါလာစီ\u001Eဂီနီရာ ဖရန့်\u001Eဂွါတီမာလာ ခက်ဇော်လ်\u001Eဂိုင်ယာနာ ဒေါ်လာ\u001Eဟောင်ကောင် ဒေါ်လာ\u001Eဟွန်ဒူးရပ်စ် လမ်းပီရာ\u001Eခရိုအေးရှား ခူးနာ\u001Eဟေတီဂူးအော်ဒ်\u001Eဟန်ဂေရီယံ ဖော်ရင့်တ်\u001Eအင်ဒိုနီးရှား ရူပီးယား\u001Eအစ္စရေး ပေါင်\u001Eအစ္စရေး ရှဲကလ်အသစ်\u001Eအိန္ဒိယ ရူပီး\u001Eအီရတ် ဒီနာ\u001Eအီရန် ရီအော်လ်\u001Eအိုက်စလန် ခရိုဏာ\u001Eဂျမေကာ ဒေါ်လာ\u001Eဂျော်ဒန် ဒီနာ\u001Eဂျပန် ယန်း\u001Eကင်ညာ သျှီလင်\u001Eကာဂျစ္စတန် ဆော်မ်\u001Eကမ္ဘောဒီးယား ရီးယဲ\u001Eကိုမိုရိုစ် ဖရန့်\u001Eမြောက်ကိုရီးယား ဝမ်\u001Eတောင်ကိုရီးယား ဝမ်\u001Eကူဝိတ် ဒီနာ\u001Eကေမန် ကျွန်းစု ဒေါ်လာ\u001Eကာဇက်စတန် ထိန်ဂျီ\u001Eလာအို ကစ်\u001Eလက်ဘနွန် ပေါင်\u001Eသီရိလင်္ကာ ရူပီး\u001Eလိုက်ဘေးရီးယား ဒေါ်လာ\u001Eလီဆိုသို လိုတီ\u001Eလစ်သူယေးနီးယားလီတားစ်\u001Eလတ်ဗီးယားလတ်\u001Eလစ်ဗျား ဒိုင်နာ\u001Eမိုရိုကို ဒရမ်\u001Eမောလ်ဒိုဗာ လယ်အို\u001Eမာလာဂါစီ အရီရရီ\u001Eမက်ဆီဒိုးနီးယား ဒီနာ\u001Eမြန်မာ ကျပ်\u001Eမွန်ဂိုးလီးယား ထူးဂရခ်\u001Eမကာအို ပါတားကား\u001Eမော်ရီတေးနီးယား အူဂီးယာ (၁၉၇၃–၂၀၁၇)\u001Eမော်ရီတေးနီးယန်း အူဂီးယာ\u001Eမောရစ်ရှ ရူပီး\u001Eမော်လ်ဒိုက် ရူးဖီရာ\u001Eမာလာဝီ ခွါးချာ\u001Eမက်ကဆီကို ပီဆို\u001Eမလေးရှား ရင်းဂစ်\u001Eမိုဇမ်ဘစ် မက်တီခယ်လ်\u001Eနမီးဘီးယား ဒေါ်လာ\u001Eနိုင်ဂျီးရီးယား နိုင်းရာ\u001Eနီကာရာဂွါ ခိုးဒိုဘာ\u001Eနော်ဝေ ခရိုဏာ\u001Eနီပေါ ရူပီး\u001Eနယူးဇီလန် ဒေါ်လာ\u001Eအိုမန်နီ ရီရယ်\u001Eပနားမား ဘလျဘိုးအာ\u001Eပီရူး ဆိုးလ်\u001Eပါပူအာ နယူးဂီနီ ခီးနာ\u001Eဖိလစ်ပိုင် ပီဆို\u001Eပါကစ္စတန် ရူပီး\u001Eပိုလန် ဇလော့တီ\u001Eပါရာဂွေး ဂွါးအ်နီး\u001Eကာတာရီ ရီရယ်\u001Eရိုမေးနီးယား လယ်အို\u001Eဆားဘီးယား ဒယ်နား\u001Eရုရှ ရူဘယ်\u001Eရုရှ ရူဘယ် (၁၉၉၁–၁၉၉၈)\u001Eရဝန်ဒါ ဖရန့်\u001Eဆော်ဒီအာရေးဗီးယား ရီယော်လ်\u001Eဆော်လမွန်ကျွန်းစု ဒေါ်လာ\u001Eဆေးရှဲ ရူပီး\u001Eဆူဒန် ပေါင်\u001Eဆူဒန် ပေါင်အဟောင်း\u001Eဆွီဒင် ခရိုဏာ\u001Eစင်္ကာပူ ဒေါ်လာ\u001Eစိန့်ဟယ်လယ်နာ ပေါင်\u001Eဆီယာရာလီယွန်း လီအိုနီ\u001Eဆီယာရာလီယွန်း လီအိုနီ (၁၉၆၄—၂၀၂၂)\u001Eဆိုမာလီ သျှီလင်\u001Eဆူရီနမ်း ဒေါ်လာ\u001Eတောင်ဆူဒန် ပေါင်\u001Eဆောင်တူမေးနှင့် ပရင်စီပီ ဒိုဘရာ\u001Eဆောင်တူမေးနှင့် ပရင်စီပီ ဒိုဘရာ (၂၀၁၈)\u001Eဆိုဗီယက် ရူဗယ်\u001Eဆီးရီးယား ပေါင်\u001Eဆွာဇီလန် လီလန်းဂီနီ\u001Eထိုင်း ဘတ်\u001Eတာဂျစ်ကစ္စတန် ဆိုမိုနီ\u001Eတာ့ခ်မင်နစ္စတန် မာနတ်\u001Eတူနီးရှား ဒိုင်နာ\u001Eတွန်ဂါ ဗန်ဂါ\u001Eရှေးဟောင်းတူရကီ လိုင်ရာ\u001Eတူရကီ လိုင်ရာ\u001Eထရီနီဒတ်နှင့် တိုဘက်ဂို ဒေါ်လာ\u001Eထိုင်ဝမ် ဒေါ်လာအသစ်\u001Eတန်ဇန်းနီးယား သျှီလင်\u001Eယူကရိန်း ဟီရီဗင်းညား\u001Eယူဂန္ဒာ သျှီလင်\u001Eအမေရိကန် ဒေါ်လာ\u001Eအမေရိကန် ဒေါ်လာ (နောက်နေ့)\u001Eအမေရိကန် ဒေါ်လာ (တနေ့တည်း)\u001Eဥရုဂွေး ပီဆို\u001Eဥဇဘက်ကစ္စတန် ဆော်မ်\u001Eဗင်နီဇွဲလား ဘိုလီဗာ (၂၀၀၈–၂၀၁၈)\u001Eဗင်နီဇွဲလန်း ဘိုလီဗာ\u001Eဗီယက်နမ် ဒေါင်\u001Eဗနွားတူ ဗားထူ\u001Eဆမိုအား ထားလာ\u001Eကင်မရွန်း ဖရန့်\u001Eငွေ\u001Eရွှေ\u001Eဥရောပငွေကြေးစံနစ်\u001Eအရှေ့ကာရစ်ဘီယံ ဒေါ်လာ\u001Eကာရစ်ဘီယံ ဂင်းဒါး\u001Eအထူးထုတ်ယူခွင့်\u001Eအနောက် အာဖရိက [CFA ]ဖရန့်\u001E[CFP] ဖရန့်\u001Eပလက်တီနမ်\u001Eစမ်းသပ် ငွေကြေး ကုဒ်\u001Eမသိသို့မဟုတ်မရှိသောငွေကြေး\u001Eယီမင်နီ ရီရယ်\u001Eတောင်အာဖရိက ရန်း\u001Eဇင်ဘာဘွေ ခွါးချာ\u001Eဇင်ဘာဘွေ ဒေါ်လာ\u001Eဇင်ဘာဘွေ ရွှေ"

